import { mkdir, readFile } from "node:fs/promises";

import { writeTextFileAtomic } from "../shared/atomic-file";
import {
  exists,
  filmPaths,
  filmRegistryPath,
  filmsRoot,
  listFilmIds,
} from "./files";

/**
 * Builds `src/films/index.ts`: static imports only, so the Remotion bundle
 * never scans directories at render time.
 */
export const renderFilmRegistrySource = (
  films: readonly { id: string; timing: boolean; music: boolean }[],
) => {
  const lines = [
    "// Generated by AXMORF Studio (film:new, film:voice, film:music). Do not edit.",
    'import type { FilmRegistryEntry } from "@axmorf/studio/remotion";',
    "",
  ];
  films.forEach(({ id, timing, music }, index) => {
    lines.push(`import spec${index} from "./${id}/film.json";`);
    if (timing) {
      lines.push(`import timing${index} from "./${id}/generated/timing.json";`);
    }
    if (music) {
      lines.push(`import music${index} from "./${id}/generated/music.json";`);
    }
  });
  if (films.length === 0) {
    lines.push(
      "export const filmRegistry: readonly FilmRegistryEntry[] = [];",
      "",
    );
    return lines.join("\n");
  }
  lines.push("", "export const filmRegistry: readonly FilmRegistryEntry[] = [");
  films.forEach(({ id, timing, music }, index) => {
    lines.push(
      "  {",
      `    spec: spec${index},`,
      `    timing: ${timing ? `timing${index}` : "null"},`,
      `    music: ${music ? `music${index}` : "null"},`,
      `    film: () => import("./${id}/Film"),`,
      `    cover: () => import("./${id}/Cover"),`,
      "  },",
    );
  });
  lines.push("];", "");
  return lines.join("\n");
};

export const generateFilmRegistry = async (rootDir: string) => {
  const films = [];
  for (const id of await listFilmIds(rootDir)) {
    const paths = filmPaths(rootDir, id);
    films.push({
      id,
      timing: await exists(paths.timing),
      music: await exists(paths.music),
    });
  }
  const source = renderFilmRegistrySource(films);
  const path = filmRegistryPath(rootDir);
  const current = (await exists(path)) ? await readFile(path, "utf8") : null;
  if (current !== source) {
    await mkdir(filmsRoot(rootDir), { recursive: true });
    await writeTextFileAtomic({
      destination: path,
      bytes: source,
      mode: "replace",
    });
  }
  return { filmCount: films.length, changed: current !== source };
};
